16	// Makeshift Mauler
17	// ═══════════════════════════════════════════════════════════════════
18	
19	#[test]
20	fn makeshift_mauler_exiles_creature_from_graveyard() {
21	    let reg = registry();
22	    let mut state = game_at_step(Step::PrecombatMain, P0);
23	
24	    // Put a creature card in P0's graveyard.
25	    let graveyard_creature = spell_in_hand(&mut state, &reg, "Walking Corpse", P0);
26	    state.move_object(graveyard_creature, Zone::Graveyard);
27	
28	    // Cast Makeshift Mauler.
29	    let mauler = castable_spell(&mut state, &reg, "Makeshift Mauler", P0);
30	    let new_state = cast_and_resolve(&state, &reg, mauler, vec![]);
31	
32	    // Mauler should be on the battlefield.
33	    assert_eq!(new_state.get_object(mauler).unwrap().zone, Zone::Battlefield);
34	    // Graveyard creature should be exiled.
35	    assert_eq!(new_state.get_object(graveyard_creature).unwrap().zone, Zone::Exile);
36	}
