38	#[test]
39	fn makeshift_mauler_is_4_5_zombie() {
40	    let reg = registry();
41	    let mut state = game_at_step(Step::PrecombatMain, P0);
42	    let graveyard_creature = spell_in_hand(&mut state, &reg, "Walking Corpse", P0);
43	    state.move_object(graveyard_creature, Zone::Graveyard);
44	
45	    let mauler = castable_spell(&mut state, &reg, "Makeshift Mauler", P0);
46	    let new_state = cast_and_resolve(&state, &reg, mauler, vec![]);
47	
48	    assert_eq!(new_state.effective_power(mauler, &reg).unwrap(), 4);
49	    assert_eq!(new_state.effective_toughness(mauler, &reg).unwrap(), 5);
50	}
