57	fn stitched_drake_exiles_creature_and_has_flying() {
58	    let reg = registry();
59	    let mut state = game_at_step(Step::PrecombatMain, P0);
60	
61	    let graveyard_creature = spell_in_hand(&mut state, &reg, "Grizzly Bears", P0);
62	    state.move_object(graveyard_creature, Zone::Graveyard);
63	
64	    let drake = castable_spell(&mut state, &reg, "Stitched Drake", P0);
65	    let new_state = cast_and_resolve(&state, &reg, drake, vec![]);
66	
67	    assert_eq!(new_state.get_object(drake).unwrap().zone, Zone::Battlefield);
68	    assert_eq!(new_state.get_object(graveyard_creature).unwrap().zone, Zone::Exile);
69	    assert_eq!(new_state.effective_power(drake, &reg).unwrap(), 3);
70	    assert_eq!(new_state.effective_toughness(drake, &reg).unwrap(), 4);
71	    // Flying is checked via keywords on the card data.
72	    let card_data = reg.card_data(new_state.get_object(drake).unwrap().card_id).unwrap();
73	    assert!(card_data.keywords.contains(&Keyword::Flying));
74	}
