    // Put two Zombies in graveyard.
    let zombie1 = spell_in_hand(&mut state, &reg, "Walking Corpse", P0);
    state.move_object(zombie1, Zone::Graveyard);
    let zombie2 = spell_in_hand(&mut state, &reg, "Diregraf Ghoul", P0);
