#[test]
fn purify_the_grave_exiles_card_from_graveyard() {
    let reg = registry();
    let mut state = game_at_step(Step::PrecombatMain, P0);

    // Put a card in P1's graveyard.
    let gy_card = spell_in_hand(&mut state, &reg, "Grizzly Bears", P1);
